{
  "meetingType": "team_sync",
  "overview": null,
  "sections": [
    {
      "title": {
        "text": "Logistics and Site Preparation",
        "sources": [
          "R1",
          "R2",
          "R10",
          "R15"
        ]
      },
      "items": [
        {
          "text": "The gallery inspection confirmed the loading door is wide enough for the largest crate and the lift is functional.",
          "sources": [
            "R1"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        },
        {
          "text": "The entrance includes a bench by the coat hooks; the access inspection confirmed the route and doorway.",
          "sources": [
            "R10",
            "R15"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        }
      ]
    },
    {
      "title": {
        "text": "Artwork and Documentation",
        "sources": [
          "R0",
          "R6",
          "R7",
          "R8",
          "R9"
        ]
      },
      "items": [
        {
          "text": "The artwork courier will be booked by Thursday once the insurance certificate is approved.",
          "sources": [
            "R0"
          ],
          "kind": "action",
          "owner": "Priya",
          "due": "Thursday"
        },
        {
          "text": "The artist descriptions vary in tone and should be preserved as such.",
          "sources": [
            "R6"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        },
        {
          "text": "The printed catalogue is limited to 100 copies due to budget constraints; a QR link is provided for additional readers.",
          "sources": [
            "R8"
          ],
          "kind": "decision",
          "owner": null,
          "due": null
        },
        {
          "text": "The catalogue PDF and QR link are already functional and contain the same artist descriptions as the printed copies.",
          "sources": [
            "R9"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        }
      ]
    },
    {
      "title": {
        "text": "Visitor Experience and Promotion",
        "sources": [
          "R4",
          "R5",
          "R11",
          "R17"
        ]
      },
      "items": [
        {
          "text": "Omar offered to record a narrated audio tour; the offer remains unaccepted.",
          "sources": [
            "R4",
            "R16"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        },
        {
          "text": "Trial observations showed varied visitor preferences regarding commentary and reading.",
          "sources": [
            "R5"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        },
        {
          "text": "Artists expressed a range of emotions regarding their work, which is part of the exhibition's understanding.",
          "sources": [
            "R11"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        },
        {
          "text": "The small completed preview should be distinguished from the future public opening.",
          "sources": [
            "R17"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        }
      ]
    },
    {
      "title": {
        "text": "Internal Coordination",
        "sources": [
          "R12",
          "R13",
          "R14",
          "R18",
          "R19"
        ]
      },
      "items": [
        {
          "text": "Priya will send the existing floor plan to Lena by Thursday for use in visitor conversations.",
          "sources": [
            "R18"
          ],
          "kind": "action",
          "owner": "Priya",
          "due": "Thursday"
        },
        {
          "text": "The promise to replace the camera equipment list was withdrawn as the folder already contains the corrected list.",
          "sources": [
            "R12",
            "R13"
          ],
          "kind": "decision",
          "owner": null,
          "due": null
        }
      ]
    }
  ],
  "recentWin": {
    "win": {
      "text": "The gallery inspection confirmed the loading door is wide enough for the largest crate and the lift worked during the visit.",
      "sources": [
        "R1"
      ]
    },
    "impact": {
      "text": "The team confirmed the route from the street and the feasibility of moving pieces to the gallery.",
      "sources": [
        "R1"
      ]
    }
  }
}

